// Hero der Seite /energiegemeinschaften/software
import { BadgeCheck, Check } from "lucide-react";
import Breadcrumbs from "@/components/ui/Breadcrumbs";
import Button from "@/components/ui/Button";
import { Eyebrow } from "@/components/ui/SectionHeading";
import { cn } from "@/components/ui/cn";
import { HeroKomposition } from "@/components/Portal/EG/Produkt/Mockups";

const HERO_CHIPS = ["Geführte Zustimmung beim Netzbetreiber", "Mehrfachteilnahme bis fünf Gemeinschaften", "Gründung, Wechsel und Betrieb", "EDA-Rolle bleibt bei der Gemeinschaft"];

export default function Hero() {
  return (
    <section data-abschnitt="hero" className="ov-verlauf-nacht ov-noise relative isolate overflow-hidden text-white">
      <div aria-hidden="true" className="ov-grid-bg absolute inset-0 -z-10 opacity-60" />
      <div className="ov-container pb-24 pt-8 md:pb-28 md:pt-12">
        <Breadcrumbs items={[{ name: "Energiegemeinschaften", href: "/energiegemeinschaften" }, { name: "Plattform & Betrieb" }]} dark className="ov-hero-in mb-10" />
        <div className="grid items-center gap-14 lg:grid-cols-[minmax(0,0.9fr)_minmax(0,1.1fr)] lg:gap-10">
          <div className="max-w-2xl">
            <div className="ov-hero-in" style={{ "--ov-delay": "60ms" }}><Eyebrow dark className="mb-5">Für Energiegemeinschaften in Österreich · ElWG</Eyebrow></div>
            <h1 className="ov-h1 ov-hero-in" style={{ "--ov-delay": "120ms" }}>Die Gemeinschaft führen – <span className="ov-text-gradient-light">nicht nur abrechnen.</span></h1>
            <p className="ov-lead ov-hero-in mt-6 text-white/75" style={{ "--ov-delay": "200ms" }}>Mitgliederportal, Abrechnung mit Vier-Augen-Freigabe und geführte Zustimmung beim Netzbetreiber – als Software für Ihren Vorstand oder mit uns als Organisator im Betrieb.</p>
            <ul className="ov-hero-in mt-7 flex flex-wrap gap-2" style={{ "--ov-delay": "260ms" }}>
              {HERO_CHIPS.map((x, i) => (
                <li key={x} className={cn("ov-glass inline-flex items-center gap-2 rounded-full px-3.5 py-1.5 text-[13.5px] text-white/90", i > 1 && "hidden sm:inline-flex")}><Check aria-hidden="true" className="h-3.5 w-3.5 text-ov-300" strokeWidth={3} />{x}</li>
              ))}
            </ul>
            <div className="ov-hero-in mt-9 flex flex-col gap-3 sm:flex-row sm:flex-wrap" style={{ "--ov-delay": "320ms" }}>
              <Button href="#anfrage" size="lg" pfeil className="w-full sm:w-auto">Angebot anfragen</Button>
              <Button href="#produkt" size="lg" variant="outlineLight" className="w-full sm:w-auto">Plattform ansehen</Button>
            </div>
            <p className="ov-hero-in mt-4 text-[13px] text-white/75" style={{ "--ov-delay": "360ms" }}>Unverbindlich · Angebot nach Größe und Paket · auch für bestehende Gemeinschaften</p>
            <div className="ov-hero-in mt-6 flex flex-col items-start gap-3" style={{ "--ov-delay": "400ms" }}>
              <a href="#elwg" className="ov-glass inline-flex items-center gap-2 rounded-full px-3.5 py-1.5 text-[13.5px] text-white/90 transition-colors hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-300">
                <BadgeCheck aria-hidden="true" className="h-4 w-4 shrink-0 text-ov-300" />Seit 1. Oktober 2026: neue ElWG-Regeln – was sich ändert
              </a>
              <p className="text-[14px] text-white/75">Mitglied oder Interessent? <a href="#rechner" className="rounded font-semibold text-white underline decoration-ov-300 underline-offset-4 hover:decoration-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-300">Ersparnis rechnen</a></p>
            </div>
          </div>
          <div className="relative lg:mt-6 lg:self-start">
            {/* Bühne: Lichtkegel hinter dem Produkt und Bodenschatten unter der Komposition */}
            <div aria-hidden="true" className="pointer-events-none absolute -inset-x-10 -inset-y-16 -z-10 rounded-full bg-[radial-gradient(closest-side,rgba(140,186,88,0.28),transparent_70%)] blur-2xl" />
            <div aria-hidden="true" className="pointer-events-none absolute inset-x-[12%] bottom-6 -z-10 h-16 rounded-[50%] bg-navy-950/60 blur-2xl" />
            <HeroKomposition />
            <p className="mt-16 text-center text-[12.5px] text-white/70 sm:mt-24">Beispielansicht mit fiktiven Werten</p>
          </div>
        </div>
      </div>
    </section>
  );
}
// Faktenleiste – Regeln, die die Plattform abbildet
import { BadgeCheck, BellRing, Check, Repeat } from "lucide-react";
import { cn } from "@/components/ui/cn";

/** Produktfakten – Regeln, die die Plattform abbildet (keine Unternehmenskennzahlen) */
const FAKTEN = [
  { icon: Repeat, wert: "5", einheit: "Gemeinschaften", text: "je Zählpunkt – Teilnahmefaktoren im Blick" },
  { icon: BellRing, wert: "10", einheit: "Werktage", text: "Zustimmungsfrist – das Portal zählt für jedes Mitglied mit" },
  { icon: BadgeCheck, wert: "2", einheit: "Freigaben", text: "Vier-Augen-Prinzip für jede Abrechnung und Zahlung" },
  { icon: Check, wert: "0", einheit: "Neuanmeldungen", text: "beim Wechsel – die Zustimmungen der Mitglieder bleiben gültig" },
];

export default function Fakten() {
  return (
    <section data-abschnitt="fakten" aria-labelledby="fakten-titel" className="relative z-10 -mt-12 md:-mt-16">
      <h2 id="fakten-titel" className="sr-only">Regeln, die die Plattform abbildet</h2>
      <div className="ov-container">
        <dl className="relative grid grid-cols-2 rounded-[2rem] bg-white p-2 shadow-e4 ring-1 ring-ink-200/70 before:absolute before:inset-x-10 before:top-0 before:h-px before:bg-gradient-to-r before:from-transparent before:via-ov-300 before:to-transparent md:grid-cols-4">
          {FAKTEN.map((f, i) => (
            <div key={f.text} className={cn("flex flex-col p-4 md:p-6", i % 2 === 1 && "border-l border-ink-100", i >= 2 && "border-t border-ink-100 md:border-t-0", i === 2 && "md:border-l")}>
              <dt className="order-last mt-1 text-[13.5px] leading-snug text-ink-600">{f.text}</dt>
              <dd>
                <span aria-hidden="true" className="mb-3 flex h-9 w-9 items-center justify-center rounded-xl bg-ov-50 text-ov-600 ring-1 ring-ov-200"><f.icon className="h-4 w-4" /></span>
                <span className="ov-kpi-l block text-ink-900">{f.wert}<span className="ov-einheit text-ov-700"> {f.einheit}</span></span>
              </dd>
            </div>
          ))}
        </dl>
      </div>
    </section>
  );
}
